import React, { useState } from 'react';
import { useStore } from '../../context/StoreContext';
import { AppTab, ProfilePersona } from '../../types';
import {
  Calendar,
  BookOpen,
  CheckSquare,
  Sparkles,
  BookMarked,
  User,
  Users,
  Plus,
  Palette,
  X,
  Settings,
} from 'lucide-react';

interface HeaderProps {
  onOpenAddModal: () => void;
}

const PERSONA_COLORS = [
  { label: 'Royal Blue', hex: '#2563eb' },
  { label: 'Vibrant Pink', hex: '#ec4899' },
  { label: 'Purple', hex: '#7c3aed' },
  { label: 'Emerald', hex: '#059669' },
  { label: 'Rose', hex: '#e11d48' },
  { label: 'Amber', hex: '#d97706' },
  { label: 'Cyan', hex: '#0891b2' },
  { label: 'Indigo', hex: '#4f46e5' },
];

export const Header: React.FC<HeaderProps> = ({ onOpenAddModal }) => {
  const {
    activeProfile,
    setActiveProfile,
    activeTab,
    setActiveTab,
    profileColors,
    setProfileColor,
    setIsSettingsOpen,
  } = useStore();

  const [colorPickerTarget, setColorPickerTarget] = useState<ProfilePersona | null>(null);

  const navItems: { tab: AppTab; label: string; icon: React.ReactNode }[] = [
    { tab: 'calendar', label: 'Calendar', icon: <Calendar className="w-4 h-4" /> },
    { tab: 'classes', label: 'Classes', icon: <BookOpen className="w-4 h-4" /> },
    { tab: 'todo', label: 'To-Do', icon: <CheckSquare className="w-4 h-4" /> },
    { tab: 'habits', label: 'Habits', icon: <Sparkles className="w-4 h-4" /> },
    { tab: 'books', label: 'Books', icon: <BookMarked className="w-4 h-4" /> },
  ];

  const profiles: ProfilePersona[] = ['Eve', 'Abbie', 'Both'];

  return (
    <header className="sticky top-0 z-30 bg-white/90 backdrop-blur-md border-b border-slate-200/60 px-3 sm:px-4 md:px-6 py-2.5 transition-all max-w-full">
      <div className="max-w-7xl mx-auto flex items-center justify-between gap-2 sm:gap-3">
        {/* Left: Brand Logo */}
        <div className="flex items-center gap-2 sm:gap-3 shrink-0">
          <button
            onClick={() => setActiveTab('calendar')}
            className="flex items-center gap-1.5 text-left group focus:outline-none shrink-0"
          >
            <div className="w-7 h-7 sm:w-8 sm:h-8 rounded-xl bg-slate-900 flex items-center justify-center text-white shadow-xs group-hover:scale-105 transition-transform">
              <Calendar className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-white stroke-[2.5]" />
            </div>
            <span className="hidden min-[360px]:inline text-base sm:text-lg font-bold tracking-tight text-slate-900">
              calender<span className="text-pink-500">.</span>
            </span>
          </button>

          {/* Desktop Nav Tabs */}
          <nav className="hidden lg:flex items-center gap-1 bg-slate-100/80 p-1 rounded-xl border border-slate-200/50">
            {navItems.map((item) => {
              const isActive = activeTab === item.tab;
              return (
                <button
                  key={item.tab}
                  onClick={() => setActiveTab(item.tab)}
                  className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold transition-all ${
                    isActive
                      ? 'bg-white text-slate-900 shadow-xs'
                      : 'text-slate-600 hover:text-slate-900 hover:bg-slate-200/50'
                  }`}
                >
                  {item.icon}
                  <span>{item.label}</span>
                </button>
              );
            })}
          </nav>
        </div>

        {/* Center: Desktop Add Button */}
        <div className="hidden lg:flex flex-1 justify-center max-w-xs">
          <button
            onClick={onOpenAddModal}
            className="flex items-center justify-center gap-1.5 bg-slate-900 hover:bg-slate-800 active:scale-95 text-white font-semibold px-4 py-1.5 rounded-xl text-xs shadow-xs transition-all cursor-pointer"
          >
            <Plus className="w-4 h-4 stroke-[2.5]" />
            <span>Add Item</span>
          </button>
        </div>

        {/* Right: Persona Switcher & Settings */}
        <div className="flex items-center gap-1 sm:gap-1.5 shrink-0">
          {/* Segmented Persona Switcher */}
          <div className="flex items-center bg-slate-100 p-1 rounded-2xl border border-slate-200/60 gap-0.5">
            {profiles.map((p) => {
              const isSelected = activeProfile === p;
              const currentColor = profileColors[p] || (p === 'Eve' ? '#2563eb' : p === 'Abbie' ? '#ec4899' : '#059669');

              return (
                <button
                  key={p}
                  onClick={() => setActiveProfile(p)}
                  className={`flex items-center justify-center gap-1 px-2.5 sm:px-3 min-h-[36px] sm:min-h-[40px] rounded-xl text-xs font-semibold transition-all cursor-pointer ${
                    isSelected ? 'text-white shadow-2xs' : 'text-slate-600 hover:text-slate-900 hover:bg-white/70'
                  }`}
                  style={isSelected ? { backgroundColor: currentColor } : undefined}
                >
                  {p === 'Both' ? <Users className="w-3.5 h-3.5" /> : <User className="w-3.5 h-3.5" />}
                  <span className="hidden min-[400px]:inline">{p}</span>
                </button>
              );
            })}
          </div>

          {/* Settings Button */}
          <button
            onClick={() => setIsSettingsOpen(true)}
            className="flex items-center justify-center gap-1 min-h-[36px] px-2.5 sm:min-h-[40px] sm:px-3 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 border border-slate-200/60 transition-all cursor-pointer shrink-0"
            title="App Settings"
          >
            <Settings className="w-4 h-4" />
            <span className="text-[11px] font-bold">Settings</span>
          </button>
        </div>
      </div>

      {/* PERSONA COLOR PICKER MODAL */}
      {colorPickerTarget && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-xs animate-fade-in">
          <div className="bg-white rounded-3xl p-6 border border-slate-200 shadow-2xl max-w-sm w-full space-y-4 animate-slide-up">
            <div className="flex items-center justify-between border-b border-slate-100 pb-3">
              <div className="flex items-center gap-2">
                <Palette className="w-5 h-5 text-blue-600" />
                <h3 className="text-base font-bold text-slate-900">
                  Customize Color for {colorPickerTarget}
                </h3>
              </div>
              <button
                onClick={() => setColorPickerTarget(null)}
                className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-500 hover:bg-slate-200"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            <p className="text-xs text-slate-500 font-medium">
              Choose a unique persona color for {colorPickerTarget} so Eve and Abbie are visually distinct:
            </p>

            <div className="grid grid-cols-4 gap-2.5 pt-1">
              {PERSONA_COLORS.map((c) => (
                <button
                  key={c.label}
                  onClick={async () => {
                    await setProfileColor(colorPickerTarget, c.hex);
                    setColorPickerTarget(null);
                  }}
                  className="flex flex-col items-center justify-center p-2.5 rounded-xl border border-slate-200 hover:border-slate-400 transition-all gap-1.5 text-xs font-semibold cursor-pointer"
                >
                  <div
                    className="w-6 h-6 rounded-full border border-slate-300/50 shadow-xs"
                    style={{ backgroundColor: c.hex }}
                  />
                  <span className="text-[11px] text-slate-700">{c.label}</span>
                </button>
              ))}
            </div>
          </div>
        </div>
      )}
    </header>
  );
};


